  }
  def fcac-incomplete-reason(state,count,evidence,fallback) = if not(fcac-reply-exhausted(state,count)) then fallback else if str_eq(evidence,"") then "reply-token-budget-reached;partial-reply-retention-failed;no-action" else "reply-token-budget-reached;partial-reply-retained;no-action";
  def fcac-replied(session,state,raw,checker,turns,started) {
   let evidence = fcac-retain-reply(raw);
   let syntax = fcac-syntax-before(state,raw,evidence);
   let next = fcap-native-submission-admitted(fcap-step(state,raw,checker),raw);
   let reobserved = fcac-syntax-after(state,raw,next,syntax);
   let shape = fcap-reply-shape(state,raw,next);
   print_str(str_concat("form-code-reply ",json-emit(json-node-object(append(json-object-pairs(shape),list(json-node-pair("reply_evidence",if str_eq(evidence,"") then json-node-null() else json-node-string(evidence))))))));
   fcac-advance(session,next,checker,turns,started);
  }
  def fcac-syntax-reading(state,raw,evidence) {
   let end = faj-complete(raw);
   let valid = ge(end,0);
   let prior = eq(str_find(fcap-note(state),"JSON syntax failure: ",0),0);
