   let valid = if nothing?(candidate) then 0 else and(faj-valid(candidate),and(str_eq(fcap-string(row,"before_sha256"),hex-encode(sha256-stream-string(raw))),str_eq(fcap-string(row,"after_sha256"),hex-encode(sha256-stream-string(candidate)))));
