   let applied = oh-applied(reading,"revise",json-node-object(list(oh-s("state","awaiting-corrected-response"),oh-s("coding_stage",fcap-stage(next)))));
   oh-voice(applied);
   applied;
  } else {
   let row = parse-json("native-json-repair",head(reverse(fcap-json-repairs(next))));
   oh-voice(oh-applied(reading,"repair-json-delimiter",row));
   let fresh = fcac-syntax-reobserved(raw,reading,row);
   oh-voice(fresh);
