"},{"path":"form/form-stdlib/form-cli-model-session.fk","first_line":1,"line_count":0,"scope":"complete file","whole_source_sha256":"9a94300e0f7adbc3327f7e39f6c3ed3b48e3933789b716e3b46fc8401610e7d5","text":"; form-cli-model-session.fk — one resident Qwen context across executable
; Form observations, without re-encoding model output the body already holds.
;
; A Qwen transformer consumes integer embedding IDs. That boundary remains the
; model's physical shape. What this cell removes is the avoidable round trip:
;
;   generated ids -> decoded bytes -> whole transcript -> generated ids again
;
; The initial user turn is encoded once. Generation then returns both decoded
; text and the exact IDs that produced it while retaining the same q38 stream
; state and KV rows. A Form observation encodes only its newly born bytes plus
; the small ChatML role crossing, prefills those IDs at the current position,
; and resumes from the first predicted reply ID. BML/BMF still consumes the
; decoded bytes directly through its own cursor; no tokenizer pre-step shapes
; that grammar.
;
; The final generated ID is deliberately held pending. q38-forward consumes an
; ID at a position and predicts the next one, so the newest prediction has not
; entered KV yet. Before an observation is injected, that pending ID is placed
; exactly once. If it is already a stop ID, it supplies the assistant close;
; otherwise the close ID is appended after it. This is the same seed boundary
; whose earlier omission the live heed cursor exposed.
;
; This cell owns stream state, not weights: the surrounding q38 context and the
; per-conversation state are both explicit and both released. No persistence,
; model weight update, or remote call is implied.
;
; preludes: form-stdlib/form-cli-model-generate.fk form-stdlib/model-registry.bml form-stdlib/bml/form-cli-model-admission.bml form-stdlib/bml/form-cli-model-observation.bml form-stdlib/bml/form-cli-model-adapter.bml
; Proven by: form-stdlib/tests/form-cli-model-session-band.fk

(do
    ; session = tag status reason path src ctx sts maxpos pos pending
    ;           stopped prompt-ids generated-ids injected-ids observation-count
    (defn fcms-session (status reason path src ctx sts maxpos pos pending stopped
                        prompt-ids generated-ids injected-ids observations)
        (list "form-cli-model-session-v1" status reason path src ctx sts maxpos
              pos pending stopped prompt-ids generated-ids injected-ids observations))
    (defn fcms-status (s) (nth s 1))
    (defn fcms-reason (s) (nth s 2))
    (defn fcms-path (s) (nth s 3))
    (defn fcms-src (s) (nth s 4))
    (defn fcms-ctx (s) (nth s 5))
    (defn fcms-sts (s) (nth s 6))
    (defn fcms-maxpos (s) (nth s 7))
    (defn fcms-pos (s) (nth s 8))
    (defn fcms-pending (s) (nth s 9))
    (defn fcms-stopped? (s) (nth s 10))
    (defn fcms-prompt-ids (s) (nth s 11))
    (defn fcms-generated-ids (s) (nth s 12))
    (defn fcms-injected-ids (s) (nth s 13))
    (defn fcms-observations (s) (nth s 14))
    (defn fcms-live? (s) (if (str_eq (fcms-status s) "live") 1 0))
    (defn fcms-pending? (s) (if (ge (fcms-pending s) 0) 1 0))
    ; Status and ownership are deliberately separate. A context-window refusal
    ; can make the conversational operation `nothing` while the already-opened
    ; context and stream state still need their physical release.
    (defn fcms-resident? (s)
        (if (and (gt (len (fcms-ctx s)) 0) (gt (len (fcms-sts s)) 0)) 1 0))

    (defn fcms-none (reason)
        (fcms-session "nothing" reason "" "" (empty) (empty) 0 0 -1 0
                      0 0 0 0))
    (defn fcms-with-stream (s pos pending stopped generated injected observations)
        (fcmd-inherit s (fcms-session (fcms-status s) (fcms-reason s) (fcms-path s)
            (fcms-src s) (fcms-ctx s) (fcms-sts s) (fcms-maxpos s)
            pos pending stopped (fcms-prompt-ids s) generated injected observations)))
    (defn fcms-refuse (s reason)
        (fcmd-inherit s (fcms-session "nothing" reason (fcms-path s)
            (fcms-src s) (fcms-ctx s) (fcms-sts s) (fcms-maxpos s)
            (fcms-pos s) (fcms-pending s) (fcms-stopped? s)
            (fcms-prompt-ids s) (fcms-generated-ids s)
            (fcms-injected-ids s) (fcms-observations s))))
    (defn fcms-forward (s id pos)
        (fcmd-forward (fcms-ctx s) (fcms-sts s) (fcmd-carrier s) id pos))
    (defn fcms-refresh-head (s)
        (do
            (let pending (fcmd-pending (fcms-ctx s) (fcmd-carrier s) (fcms-pending s)))
            (let next (fcms-with-stream s (fcms-pos s) pending 0
                (fcms-generated-ids s) (fcms-injected-ids s) (fcms-observations s)))
            (if (lt pending 0) (fcms-refuse next "adapter-head-refused") next)))
    (defn fcms-attach-adapter (s path)
        (if (not (fcms-live? s)) s
            (if (not (nil? (fcmd-carrier s))) (fcms-refuse s "adapter-already-attached")
            (if (or (gt (fcms-generated-ids s) 0) (gt (fcms-observations s) 0))
                (fcms-refuse s "adapter-admission-requires-fresh-session")
                (do
                    (let admitted (fcmd-admit (fcms-ctx s) path))
                    (let owned (fcmd-with-carrier s (nth admitted 2)))
                    (if (eq (head admitted) 1) (fcms-refresh-head owned)
                        (fcms-refuse owned (nth admitted 1))))))))
    (defn fcms-open-adapted (path prompt maxpos profile adapter-path)
        (fcms-attach-adapter (fcms-open-with-profile path prompt maxpos profile) adapter-path))

    ; The API names what is and is not encoded. A live observation can report
    ; these strings without reproducing model or user content.
    (defn fcms-initial-encode-scope () "initial-user-turn-once")
    (defn fcms-resume-encode-scope () "new-observation-bytes-and-role-crossing-only")
    (defn fcms-inline-bml-encode-scope ()
        "pending-generated-id-then-new-bml-bytes-no-role-replay")
    (defn fcms-generated-id-policy () "carry-original-generated-ids-and-kv")
    (defn fcms-model-executed-form? () 0)
    (defn fcms-rejection-pending-policy ()
        "discard-uncommitted-pending-id-before-typed-observation")

    ; The living peer does not receive a made-up context width.  Its ceiling is
    ; read from the selected sealed GGUF, the same source that the carrier will
    ; open.  Absence is a typed local refusal, never an occasion to use remote.
    (defn fcms-artifact-context-capacity-from-src (src)
        (do
            (let arch (fcmg-arch src))
            (if (str_eq arch "") 0
                (gmt-u32 src (q38-key arch "context_length")))))
    (defn fcms-open-resident-agent (path prompt)
        (if (str_eq path "") (fcms-none "model-path-absent")
            (do
                (let src (fcmg-src path))
                (let capacity (fcms-artifact-context-capacity-from-src src))
                (if (le capacity 0)
                    (fcms-none "artifact-declared-context-absent")
                    (fcms-open path prompt capacity)))))

    (defn fcms-open-context
        (path src maxpos prompt-count cursor ids live-cursor x iced)
        (do
            (let span (fcma-span prompt-count))
            (let _span (q38oo-stage (str_concat "model-session-prefill-span-" (int_to_str span)) 8388624))
            (let _open-begin (q38oo-stage "model-session-context-open-begin" 8388620))
            (let ctx (if (eq iced 1)
                (qsx-open-span path maxpos x span) (q38-open-span path maxpos span)))
            (let _open-ready (q38oo-stage "model-session-context-open-ready" 8388620))
            (if (not (eq (q38-context-ok? ctx) 1))
                (do
                    (let closed (if (lt (len ctx) 10) 0
                        (q38-close ctx (empty))))
                    (fcms-none "model-context-open-refused"))
                (do
                    (let _state-begin (q38oo-stage "model-session-state-begin" 8388621))
                    (let sts (q38-new-state (nth ctx 2)))
                    (let _state-ready (q38oo-stage "model-session-state-ready" 8388621))
                    (if (not (eq (q38-state-ok? sts) 1))
                        (do
                            (let state-closed (q38-free-state sts))
                            (let context-closed (q38-close ctx (empty)))
                            (fcms-none "model-stream-state-refused"))
                        (if (eq live-cursor 1)
                            (do
                                (let _prefill-begin (q38oo-stage "model-session-prefill-begin" 8388622))
                                (let pf (fcmg-live-prefill-span ctx sts cursor))
                                (let _prefill-ready (q38oo-stage
                                    (if (str_eq (nth pf 1) "ok") "model-session-prefill-ready"
                                        "model-session-prefill-refused") 8388622))
                                (if (not (str_eq (nth pf 1) "ok"))
                                    (fcms-session "nothing" (nth pf 5)
                                        path src ctx sts maxpos (nth pf 3)
                                        -1 0 prompt-count 0 0 0)
                                    (fcms-session "live" "opened-live-cursor"
                                        path src ctx sts maxpos (nth pf 3)
                                        (nth pf 2) 0 prompt-count 0 0 0)))
                            (do
                                (let _prefill-begin (q38oo-stage "model-session-prefill-begin" 8388622))
                                (let pf (q38-prefill-span-sliced
                                    (nth ctx 0) (nth ctx 1) (nth ctx 2)
                                    (nth ctx 3) sts (nth ctx 4) (nth ctx 5)
                                    (nth ctx 6) ids 0 span))
                                (let complete (and (ge (nth pf 0) 0) (eq (nth pf 1) prompt-count)))
                                (let _prefill-ready (q38oo-stage
                                    (if complete "model-session-prefill-ready"
                                        "model-session-prefill-refused") 8388622))
                                (fcms-session (if complete "live" "nothing")
                                    (if complete "opened-scanner-fallback" "model-prefill-refused")
                                    path src ctx sts maxpos (nth pf 1) (nth pf 0) 0
                                    prompt-count 0 0 0))))))))

    ; The PROFILE names which chat shape wraps the prompt: "full" arms
    ; the teach-layer control grammar (its <FAIL> is a typed decline, not
    ; model failure); "knowledge-query" is the plain chat segments with
    ; no control overlay — the shape for probes and comparisons that
    ; want the model's own words. fcms-open keeps "full", the served
    ; default; fcms-open-with-profile is the same door with the shape
    ; chosen by the caller as data.
    (defn fcms-open (path prompt maxpos)
        (fcms-open-with-profile path prompt maxpos "full"))
    (defn fcms-open-with-profile (path prompt maxpos profile)
        (fcms-open-sized path prompt maxpos profile 0))
    ; Allocate from the counted prompt plus the caller's output/observation
    ; reserve. Artifact capacity is still checked before model admission.
    (defn fcms-open-reserved (path prompt reserve profile)
        (if (le reserve 0) (fcms-none "session-output-reserve-refused")
            (fcms-open-sized path prompt 0 profile reserve)))
    (defn fcms-open-sized (path prompt requested-maxpos profile reserve)
        (do
            (let _seal-begin (fcmg-live-stage "model-session-seal-begin" 8388609))
            (let verdict (qaf-seal-verdict path))
            (let _seal-complete (fcmg-live-stage "model-session-seal-complete" 8388610))
            (if (not (eq verdict 1))
                (fcms-none (fcmg-seal-refusal verdict))
                (do
                    (let _header-begin (fcmg-live-stage
                        "model-session-header-begin" 8388614))
                    (let src (fcmg-src path))
                    (let _header-complete (fcmg-live-stage
                        "model-session-header-complete" 8388615))
                    (let arch (fcmg-arch src))
                    ; admission by the lane table, never a literal: an arch
                    ; whose lane is not yet wired into this door refuses
                    ; TYPED, naming the lane that would serve it.
                    (if (not (eq (mr-wired? arch) 1))
                        (fcms-none (str_concat "lane-unwired:"
                            (str_concat (mr-lane-for arch)
                                (str_concat ":" arch))))
                        (do
                            (let _crystal-begin (fcmg-live-stage
                                "model-session-tokenizer-crystal-begin" 8388616))
                            (let x (qsx-load path))
                            (let _crystal-complete (fcmg-live-stage
                                "model-session-tokenizer-crystal-complete" 8388617))
                            (let iced (if (eq (nth x 0) 1) 1 0))
                            (let _cursor-begin (fcmg-live-stage
                                "model-session-prompt-cursor-begin" 8388618))
                            (let cursor0 (if (eq iced 1)
                                (fcmg-chat-cursor-profile
                                    path prompt profile x)
                                (qtlc-open-index
                                    (list "absent" "crystal-absent" ""
                                        0 0 0 0 0 0 0) (empty))))
                            (let live-cursor
                                (if (str_eq (qtlc-status cursor0) "open")
                                    1 0))
                            ; Exact count without a retained prompt-ID list.
                            ; The immutable cursor is then reopened for prefill.
                            (let counted (if (eq live-cursor 1)
                                (qtlc-count cursor0)
                                (list "fallback" cursor0)))
                            (let count-ok (if (eq live-cursor 1)
                                (if (str_eq (nth counted 0) "done") 1 0) 1))
                            (let _cursor-complete (fcmg-live-stage
                                "model-session-prompt-cursor-complete" 8388619))
                            (let ids (if (eq live-cursor 1) (empty)
                                (fcmg-chat-ids-profile src prompt profile)))
                            (let _count-begin (fcmg-live-stage
                                "model-session-prompt-count-begin" 8388620))
                            (let prompt-count (if (eq live-cursor 1)
                                (qtlc-token-count (nth counted 1))
                                (len ids)))
                            (let maxpos (if (gt reserve 0)
                                (add prompt-count reserve) requested-maxpos))
                            (let _count-complete (fcmg-live-stage
                                "model-session-prompt-count-complete" 8388621))
                            (let _positions (q38oo-stage
                                (str_concat "model-session-prompt-positions-" (int_to_str prompt-count)) 8388625))
                            (let _reopen-begin (fcmg-live-stage
                                "model-session-prompt-cursor-reopen-begin" 8388622))
                            (let cursor (if (eq live-cursor 1)
                                (fcmg-chat-cursor-profile
                                    path prompt profile x)
                                cursor0))
                            (let _reopen-complete (fcmg-live-stage
                                "model-session-prompt-cursor-reopen-complete" 8388623))
                            (if (not (eq count-ok 1))
                                (fcms-none (str_concat
                                    "live-prompt-count-refused:"
                                    (qtlc-reason (nth counted 1))))
                            (if (le prompt-count 0)
                                (fcms-none "initial-turn-encoded-no-ids")
                            (if (or (le maxpos prompt-count)
                                    (gt maxpos (gmt-u32 src
                                        (q38-key arch "context_length"))))
                                (fcms-none "session-context-window-refused")
                                (do
                                    (let _admit-begin (fcmg-live-stage
                                        "model-session-open-prefill-begin" 8388611))
                                    (let opened (fcms-open-context path src maxpos prompt-count
                                        cursor ids live-cursor x iced))
                                    (let _admit-complete (fcmg-live-stage
                                        "model-session-open-prefill-complete" 8388612))
                                    opened))))))))))

    ; Decoder progress is observable without disclosing its token or text.
    ; Checkpoints arrive after 1, 2, 4, 8... local steps: O(log n) terminal
    ; frames retain liveness for an unbounded turn without turning a long
    ; answer into a second token stream.
    (defn fcms-decode-checkpoint? (steps-to-checkpoint)
        (if (le steps-to-checkpoint 1) 1 0))
    (defn fcms-decode-next-left (steps-to-checkpoint checkpoint-width)
        (if (eq (fcms-decode-checkpoint? steps-to-checkpoint) 1)
            checkpoint-width
            (sub steps-to-checkpoint 1)))
    (defn fcms-decode-next-width (steps-to-checkpoint checkpoint-width)
        (if (eq (fcms-decode-checkpoint? steps-to-checkpoint) 1)
            (mul checkpoint-width 2)
            checkpoint-width))
    (defn fcms-decode-pulse (completed-steps)
        (fcmg-live-stage (str_concat "model-session-decode-checkpoint-"
            (int_to_str completed-steps)) 8388613))

    ; result = (ids pending pos stopped). Returned ids are model speech only;
    ; the stop/control prediction is retained separately for the next crossing.
    (defn fcms-walk (s id pos left stops out steps-to-checkpoint checkpoint-width completed-steps)
        (if (lt id 0) (list out -1 pos 1)
        (if (eq (q38-stop? id stops) 1) (list out id pos 1)
        (if (le left 0) (list out id pos 0)
            (do
                (let out2 (append out (list id)))
                (let completed2 (add completed-steps 1))
                (let pulse (if (eq (fcms-decode-checkpoint? steps-to-checkpoint) 1)
                    (fcms-decode-pulse completed2) 0))
                (let next-left (fcms-decode-next-left steps-to-checkpoint checkpoint-width))
                (let next-width (fcms-decode-next-width steps-to-checkpoint checkpoint-width))
                (if (eq left 1) (list out2 id pos 0)
                    (do
                        (let nid (fcms-forward s id pos))
                        (if (lt nid 0) (list out2 -1 (add pos 1) 1)
                        (if (eq (q38-stop? nid stops) 1)
                            (list out2 nid (add pos 1) 1)
                            (fcms-walk s nid (add pos 1) (sub left 1)
                                stops out2 next-left next-width completed2))))))))))

    ; generation = tag text ids updated-session. No generated text is needed to
    ; resume; the bytes are exposed only for the Form/BMF boundary that asks.
    (defn fcms-generation (text ids session)
        (list "form-cli-model-session-generation-v1" text ids session))
    (defn fcms-generation-text (g) (nth g 1))
    (defn fcms-generation-ids (g) (nth g 2))
    (defn fcms-generation-session (g) (nth g 3))
    (defn fcms-generate (s n)
        (if (or (not (eq (fcms-live? s) 1)) (le n 0))
            (fcms-generation "" (empty) s)
            (do
                (let stops (fcmg-q35-stops (fcms-src s)))
                (let walked (fcms-walk s (fcms-pending s) (fcms-pos s)
                    n stops (empty) 1 1 0))
                (let ids (nth walked 0))
                (let next (fcms-with-stream s (nth walked 2) (nth walked 1)
                    (nth walked 3) (add (fcms-generated-ids s) (len ids))
                    (fcms-injected-ids s) (fcms-observations s)))
                (fcms-generation (ftdb-text (fcms-src s) ids) ids next))))

    ; The tail begins after an assistant close. It contains only newly born
    ; role/observation bytes and the fresh assistant opening.
    (defn fcms-tool-tail-ids (src text)
        (fcmo-tool-tail-ids src text))

    ; Direct questions are not tool observations.  Preserve the completed
    ; assistant token and enter the ordinary no-thinking user/assistant template.
    ; Recipe/source effects retain fcms-tool-tail-ids above.
    (defn fcms-direct-user-role () "user")
    (defn fcms-direct-answer-tail-ids (src text)
        (fcmo-direct-reference-ids src text))

