    ; once.  A rejection crossing does the opposite: that pending prediction
    ; has not entered KV, so it is discarded and only the assistant close is
    ; placed at its position.  Keeping this as one pure helper makes token 0/1
    ; testable without opening a model.
    (defn fcms-crossing-prefix-ids
        (pending pending-is-stop close-id retain-pending)
        (if (eq retain-pending 0) (list close-id)
            (do
                (let prefix (if (ge pending 0) (list pending) (empty)))
                (let close-needed
                    (if (and (ge pending 0) (eq pending-is-stop 1)) 0 1))
                (if (eq close-needed 1)
                    (tkz-cat prefix (list close-id)) prefix))))

    (defn fcms-observation-ids (s text)
        (do
            (let src (fcms-src s))
            (let stops (fcmg-q35-stops src))
            (let pending (fcms-pending s))
            (let closed (fcms-crossing-prefix-ids pending
                (if (ge pending 0) (q38-stop? pending stops) 0)
                (q35-special-id src "<|im_end|>") 1))
            (tkz-cat closed (fcms-tool-tail-ids src text))))

    (defn fcms-direct-answer-observation-ids (s text)
        (do
            (let src (fcms-src s))
            (let stops (fcmg-q35-stops src))
            (let pending (fcms-pending s))
            (let closed (fcms-crossing-prefix-ids pending
                (if (ge pending 0) (q38-stop? pending stops) 0)
                (q35-special-id src "<|im_end|>") 1))
            (let indexed (fcmo-direct-tail-ids (fcms-path s) text))
            (tkz-cat closed (if (nothing? indexed)
                (fcms-direct-answer-tail-ids src text) indexed))))

    (defn fcms-rejection-observation-ids (s text)
        (do
            (let src (fcms-src s))
            (let closed (fcms-crossing-prefix-ids (fcms-pending s) 0
                (q35-special-id src "<|im_end|>") 0))
            (tkz-cat closed (fcms-tool-tail-ids src text))))

    ; A Form execution result may continue the current assistant stream as BML
    ; instead of opening another ChatML tool/assistant pair. The pending model
    ; ID is still committed exactly once. If it is already an assistant stop,
    ; the ordinary role crossing remains the honest shape; bytes cannot be
    ; appended inside a turn that has already ended.
    (defn fcms-inline-bml-observation-ids (s text)
        (do
            (let src (fcms-src s))
            (let pending (fcms-pending s))
            (let stops (fcmg-q35-stops src))
            (if (and (ge pending 0) (eq (q38-stop? pending stops) 1))
                (fcms-observation-ids s text)
                (do
                    (let prefix (if (ge pending 0)
                        (list pending) (empty)))
                    (tkz-cat prefix (q35-encode src
                        (str_concat "\n" (str_concat text "\n"))))))))

    (defn fcms-observe-ids (s ids refusal-reason)
        (if (not (eq (fcms-live? s) 1)) s
            (if (or (eq (len ids) 0)
                    (gt (add (fcms-pos s) (len ids)) (fcms-maxpos s)))
                    (fcms-refuse s refusal-reason)
                (do
                    (let ctx (fcms-ctx s))
                    ; All IDs retain their order and the same stream state.
                    ; Submission width, unlike observation length, is bounded.
                    (let pf (fcmo-prefill ctx (fcms-sts s) ids (fcms-pos s)))
                    (if (not (fcmo-shape pf (fcms-pos s) (len ids)))
                        ; No retry may resume this state: a completed prefix or
                        ; a partially executed failing submission can be present.
                        ; Counters retain the last completed observation, not a
                        ; claim that physical KV was rolled back. Keep ownership
                        ; so the original context can still be released.
                        (fcms-refuse s "observation-prefill-refused")
                        (fcms-refresh-head (fcms-with-stream s (nth pf 1) (nth pf 0) 0
                            (fcms-generated-ids s)
                            (add (fcms-injected-ids s) (len ids))
                            (add (fcms-observations s) 1))))))))

    ; Injects one typed Form observation into the SAME q38 state. It returns a
    ; session whose pending ID is the first prediction after the observation.
    (defn fcms-observe (s text)
        (fcms-observe-ids s (fcms-observation-ids s text)
            "observation-context-window-refused"))

    (defn fcms-observe-direct-answer (s text)
        (fcms-observe-ids s (fcms-direct-answer-observation-ids s text)
            "direct-answer-context-window-refused"))

    ; Form-native execution-token shape: compact BML enters the same generated
    ; stream without paying a second role template. It remains a named choice,
    ; not a replacement for ordinary tool-role observations.
    (defn fcms-observe-inline-bml (s text)
        (fcms-observe-ids s (fcms-inline-bml-observation-ids s text)
            "inline-bml-observation-context-window-refused"))

    ; Grammar/execution rejection enters at the pending token's exact position.
    ; The rejected prediction is not included in ids and never reaches q38-forward.
    (defn fcms-observe-rejection (s text)
        (fcms-observe-ids s (fcms-rejection-observation-ids s text)
            "rejection-observation-context-window-refused"))

    (defn fcms-release-ok? (s)
        (do
            (let adapter-expected (fcmd-owned (fcmd-carrier s)))
            (if (gt adapter-expected 0) (metal_sync) 0)
            (let adapter-closed (fcmd-close (fcmd-carrier s)))
            (let adapter-ok (eq adapter-closed adapter-expected))
            (if (eq (fcms-resident? s) 0) adapter-ok
              (do
                (let state-expected (q38-state-handle-count (fcms-sts s)))
                (let state-closed (q38-free-state (fcms-sts s)))
                (let context-expected (q38-close-expected (fcms-ctx s) (empty)))
                (let context-closed (q38-close (fcms-ctx s) (empty)))
                (if (and adapter-ok (and (eq state-closed state-expected)
                         (eq context-closed context-expected))) 1 0)))))

    0)
